@import "@fontsource-variable/geist";
@import "@fontsource-variable/geist-mono";

/* Light (faithful): #fafafa page, white windows and buttons, #171717 ink for headings and
   primary buttons (hover #383838), #4d4d4d grey text, #8f8f8f faint text, #ebebeb
   hairlines and #f2f2f2 quiet fills. One blue, #0070f3, for the status line and focus. */
:root {
  --background: #fafafa;
  --foreground: #171717;
  --card: #ffffff;
  --card-foreground: #171717;
  --popover: #ffffff;
  --popover-foreground: #171717;
  --primary: #171717;
  --primary-foreground: #ffffff;
  --secondary: #ffffff;
  --secondary-foreground: #171717;
  --muted: #f2f2f2;
  --muted-foreground: #4d4d4d;
  --accent: #f2f2f2;
  --accent-foreground: #171717;
  --destructive: #da2f35;
  --destructive-foreground: #ffffff;
  --border: #ebebeb;
  --input: #ebebeb;
  --ring: #0070f3;
  --highlight: #0070f3;
  --highlight-foreground: #ffffff;
  --glow: #52aeff;
  --chart-1: #0070f3;
  --chart-2: #52aeff;
  --chart-3: #8f8f8f;
  --chart-4: #45dec5;
  --chart-5: #f5a623;
  --sidebar: #fafafa;
  --sidebar-foreground: #171717;
  --sidebar-primary: #171717;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #f2f2f2;
  --sidebar-accent-foreground: #171717;
  --sidebar-border: #ebebeb;
  --sidebar-ring: #0070f3;

  --typeface-body: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Geist Mono Variable", ui-monospace, SFMono-Regular, Menlo, monospace;
  --radius: 0.375rem;
  --page-width: 87rem;
  --page-gutter: 1.5rem;
  --section-y: 7.5rem;
}

/* Dark sibling: #0a0a0a page, #000 windows, #ededed ink and primary buttons, #a1a1a1 grey
   text, #2e2e2e hairlines, the blue lifted to #52a8ff. */
.dark {
  --background: #0a0a0a;
  --foreground: #ededed;
  --card: #000000;
  --card-foreground: #ededed;
  --popover: #111111;
  --popover-foreground: #ededed;
  --primary: #ededed;
  --primary-foreground: #0a0a0a;
  --secondary: #0a0a0a;
  --secondary-foreground: #ededed;
  --muted: #1a1a1a;
  --muted-foreground: #a1a1a1;
  --accent: #1f1f1f;
  --accent-foreground: #ededed;
  --destructive: #ff6166;
  --destructive-foreground: #0a0a0a;
  --border: #2e2e2e;
  --input: #2e2e2e;
  --ring: #52a8ff;
  --highlight: #52a8ff;
  --highlight-foreground: #0a0a0a;
  --glow: #3291ff;
  --chart-1: #52a8ff;
  --chart-2: #3291ff;
  --chart-3: #a1a1a1;
  --chart-4: #45dec5;
  --chart-5: #f5b047;
  --sidebar: #0a0a0a;
  --sidebar-foreground: #ededed;
  --sidebar-primary: #ededed;
  --sidebar-primary-foreground: #0a0a0a;
  --sidebar-accent: #1f1f1f;
  --sidebar-accent-foreground: #ededed;
  --sidebar-border: #2e2e2e;
  --sidebar-ring: #52a8ff;
}
